    let mut score = post_residual as f64;

    // Penalize small gaps that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Favor bins with fewer open bins remaining
    score -= open_bins_count as f64 * 0.2;

    // Penalize bins where the residual is close to the mean but not exactly fitting
    if bin_residual > mean_residual && bin_residual < mean_residual + next_item_size {
        score += (mean_residual - bin_residual) as f64 * 0.5;
    }

    // Reward bins that are nearly full
