pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize open bins using an exponential function
    score -= (open_bins_count as f64).exp() * 1.5;

    // Reward bins with very low residual space
    if bin_capacity - bin_residual < 32 {
        score += (bin_capacity - bin_residual) as f64 / 10.0;
    }

    // Penalize high post-residuals more heavily
    if post_residual > 50 {
        score -= (post_residual - 45) as f64 / 20.0;
    } else if post_residual > 35 {
        score -= (post_residual - 30) as f64 / 15.0;
    }

    // Reward items that fit perfectly in the bin
    if item_size == bin_residual {
        score += 12.0;
    }

    // Penalize next item that fits in the current bin
    if next_item_size > 0 && next_item_size <= bin_capacity - bin_residual {
        score -= (next_item_size as f64).ln() * 2.5;
    }

    // Adjust score based on time horizon
    let time_horizon = step_index as f64 / total_items as f64;
    if time_horizon < 0.3 {
        score += (1.0 - time_horizon) * 6.0;
    } else if time_horizon > 0.7 {
        score -= (time_horizon - 0.5) * 6.0;
    }

    // Penalize bins with no fitting items more heavily
    if fitting_bins_count == 0 {
        score -= 14.0;
    }

    // Lookahead trade-off: Penalize bins that are likely to be underutilized in the future
    if bin_capacity - bin_residual < mean_residual * 2.0 {
        score -= (bin_capacity - bin_residual) as f64 / 5.0;
    }

    score
